/**
 *  One physical/virtual monitor reported by xcap.
 * 
 *  Field accuracy varies by OS — `is_builtin` is reliable on macOS,
 *  best-effort elsewhere. `scale_factor` reflects `HiDPI`; multiply
 *  `width`/`height` by it to get device pixels (xcap returns logical
 *  pixels by default).
 */
export type MonitorInfo = {
	/**
	 *  Stable OS identifier — survives the same boot session, may
	 *  change across reboot/replug.
	 */
	id: number,
	/**  Operator-friendly name (xcap `friendly_name`, falls back to `name`). */
	name: string,
	/**
	 *  Logical pixel position of the monitor's top-left corner in the
	 *  virtual desktop coordinate space.
	 */
	x: number,
	/**  Logical pixel position of the monitor's top-left corner. */
	y: number,
	/**  Logical pixel width. */
	width: number,
	/**  Logical pixel height. */
	height: number,
	/**  `HiDPI` scale (1.0 on standard displays, 2.0 on Retina, etc.). */
	scaleFactor: number,
	/**  Refresh rate in Hz. */
	frequency: number,
	/**  `true` for the OS-designated primary monitor. */
	isPrimary: boolean,
	/**
	 *  `true` for the laptop's built-in panel (macOS reliable; other
	 *  platforms best-effort).
	 */
	isBuiltin: boolean,
};

/**  What was actually checked. A process handshake does not prove inference. */
export type ObservationEvidence = 
/**  Configuration/presence only, no successful service check. */
"none" | 
/**  The existing service adapter performed its health operation. */
"service-probe" | 
/**  Supervisor reports a completed protocol handshake and a connected peer. */
"protocol-handshake";

/**
 *  Partial GPU offload hints for llama.cpp-backed slots that exceed
 *  the GPU VRAM budget.
 * 
 *  Values are transformer layer counts:
 *  - `-1` = all layers on GPU (full load)
 *  - `0` = CPU only
 *  - positive integer N = N layers on GPU, rest on CPU
 * 
 *  The three fields target the three llama.cpp slots in the preset
 *  loadout: `chat.brain` (the 30B-A3B warm brain), `chat.fast` (the
 *  Qwen3-4B hot routing brain), and `chat.vision` (Qwen3-VL-2B).
 */
export type OffloadConfig = {
	/**  Layers of `chat.brain` on GPU. */
	brain_ngl: number,
	/**  Layers of `chat.fast` on GPU. */
	fast_ngl: number,
	/**  Layers of `chat.vision` on GPU. */
	vision_ngl: number,
};

