/**  What a room saved with a turn, so it reads the same when you reopen it. */
export type RoomEntry = 
/**  Which place said this. */
{ kind: "turn"; 
/**  The place, role and agent, with what it said. */
turn: RoomTurn } | 
/**  How the run ended. */
{ kind: "outcome"; 
/**  Rounds run, why they stopped, and what was picked or routed. */
outcome: Outcome };

/**  Something that happened while a room answers. */
export type RoomEvent = 
/**  Part of one place's running turn. */
{ kind: "agent"; 
/**  The place (`answerer-1`). */
place: string; 
/**  What happened. */
event: AgentEvent } | 
/**  A place's turn, finished and saved. */
{ kind: "turn"; 
/**  The turn. */
turn: RoomTurn } | 
/**
 *  The room's answer: rounds run, why they stopped, what was picked.
 *  Saved.
 */
{ kind: "finished"; 
/**  How it ended. */
outcome: Outcome } | 
/**
 *  A router asked for a Council, which is now answering in its own room.
 *  Saved. The Council's events follow, ending with its own `Finished`.
 */
{ kind: "escalated"; 
/**  How the router room ended. */
outcome: Outcome; 
/**  The Council. */
room: RoomThread } | 
/**  The run could not be durably completed. Any recovery copy is named. */
{ kind: "failed"; 
/**  The failure, not a successful room outcome. */
message: string };

/**  A room (`dpl.room/1`). */
export type RoomSpec = {
	/**  Always [`ROOM_SCHEMA`]. */
	schema: string,
	/**  Stable kebab-case key. */
	id: string,
	/**  Semver; a breaking change bumps the major. */
	version: string,
	/**  What it is called. */
	name: string,
	/**  The kind of room. */
	type: RoomType,
	/**  One line on what it is for. */
	summary: string,
	/**  Who sits in it. */
	seats: Seat[],
	/**  Its steps, in order. */
	phases: Phase[],
	/**  Who speaks next. */
	turn_policy: TurnPolicy,
	/**  When it stops. */
	stop: StopRule,
	/**  How one answer is chosen, when it chooses one. */
	selection?: Selection | null,
	/**  What passes from one phase to the next. */
	carry_forward: CarryForward,
	/**  What it keeps when it ends. */
	record: RecordItem[],
	/**  Where it comes from and how strong the evidence is. */
	provenance: Provenance,
};

/**
 *  One event of a room answering (plan 0001 B4.2): part of a place's
 *  running turn, a place's finished turn, or the room's outcome.
 */
export type RoomStreamed = {
	/**  The room (its chat session id). */
	sessionId: string,
	/**  What happened. */
	event: RoomEvent,
};

/**  A room of yours. */
export type RoomThread = {
	/**  The chat session it is (load its turns with the chat's history). */
	sessionId: string,
	/**  The project it belongs to. */
	projectId: string,
	/**  The library room it is (`council`). */
	roomId: string,
	/**  Its title. */
	title: string,
	/**  Who sits where. */
	seating: Assignment[],
	/**  How many turns it holds. */
	turnCount: number,
	/**  Unix seconds of its last turn. */
	updatedAt: number,
};

/**  One finished turn of a place. */
export type RoomTurn = {
	/**  Its order in this run, from 1. */
	seq: number,
	/**  The round it was in, from 1. */
	round: number,
	/**  The phase it was in. */
	phase: string,
	/**  The place (`answerer-1`). */
	place: string,
	/**  The place's seat. */
	seat: string,
	/**  The seat's role id. */
	role: string,
	/**  The persona's id, when the place has one. */
	persona: string | null,
	/**  The agent that answered. */
	provider: ProviderId,
	/**  Its letter as a candidate, when it is one. */
	candidate: string | null,
	/**  The answer, as the agent gave it. */
	text: string,
	/**  The JSON object the answer ended with. */
	output: Value | null,
	/**  How the answer broke its role's output contract. */
	contractProblem: string | null,
	/**  Why the agent could not answer. */
	failed: string | null,
};

/**  The kind of room. */
export type RoomType = 
/**  Everyone answers blind; a selector picks one answer. */
"council" | 
/**  Two sides argue; a judge selects. */
"debate" | 
/**  An author drafts; a critic from another vendor scores it. */
"author-critic" | 
/**  One seat, matched to the question. */
"router" | 
/**  Ideas first, then grouping, critique and a shortlist. */
"brainstorm" | 
/**  Everyone takes turns in a fixed order and sees everything said. */
"round-robin";

/**  What a router decided. */
export type Route = {
	/**  The place it named; absent when there was no valid answer. */
	place: string | null,
	/**  Why, in its words. */
	rationale: string | null,
	/**  It asked for a Council instead of one place. */
	escalate: boolean,
	/**  Why no one could be asked. */
	problem: string | null,
};

/**  A route's name and the lines shown with it. */
export type RouteCopy = {
	/**  Name in navigation, tiles and section headers. */
	label: string,
	/**  One line under the name on a tile. */
	blurb?: string | null,
	/**  One line under the name on the page or section itself. */
	description?: string | null,
	/**  Glossary term shown as an info chip next to the name. */
	term?: string | null,
	/**  What the entry's attention dot means, for a route that shows one. */
	badge?: string | null,
};

/**
 *  Persisted user-scope routing configuration.
 * 
 *  One TOML file (`{data_dir}/user/routing.toml`), one accessor pair
 *  (`Platform::routing_config_load` / `routing_config_save`).
 */
export type RoutingConfig = {
	/**  Escalation chain — Voice Brain → Main Brain → Cloud API. */
	escalation: EscalationConfig,
	/**  Latency tuning + response source. */
	latency: LatencyConfig,
};

/**
 *  Primary routing mode for chat and escalation decisions.
 * 
 *  These are the three explicit product modes exposed in setup:
 *  - `local_first` - prefer local inference first
 *  - `local_claude_subscription` - prefer local and escalate through the Claude subscription lane
 *  - `local_claude_api_council` - prefer local and allow both Claude subscription and API council escalation
 */
export type RoutingMode = 
/**  Prefer local inference — no cloud escalation. */
"local_first" | 
/**  Prefer local, escalate through the Claude subscription lane. */
"local_claude_subscription" | 
/**  Prefer local, escalate through both Claude subscription and API council lanes. */
"local_claude_api_council";

/**  One row: its `rowid` and a cell per column, in column order. */
export type Row = {
	/**  The row's `rowid` — how edits address it. */
	rowid: number,
	/**  One cell per column of the table, in column order. */
	cells: Cell[],
};

/**  A page of a table's rows, with the columns that describe them. */
export type RowPage = {
	/**  The table. */
	table: string,
	/**  The table's columns, in order. */
	columns: Column[],
	/**  The rows on this page, in `rowid` order. */
	rows: Row[],
	/**  Rows in the whole table. */
	total: number,
	/**  Index of the first row on this page. */
	offset: number,
};

/**
 *  Deliberation depth — how deeply Clyffy ruminates before acting.
 * 
 *  SSOT: `signals.registry.yaml` → group `rro` → attribute `rro.depth`.
 */
export type RroDepth = 
/**  Fast-path, minimal deliberation. */
"shallow" | 
/**  Standard deliberation. */
"normal" | 
/**  Extended deliberation. */
"deep";

/**
 *  RRO lifecycle state.
 * 
 *  SSOT: `signals.registry.yaml` → group `rro` → attribute `rro.state`.
 */
export type RroState = 
/**  No active RRO. */
"idle" | 
/**  Collecting relevant context. */
"gathering" | 
/**  Structuring collected context. */
"processing" | 
/**  Weighing alternatives before committing. */
"ruminating" | 
/**  Context prepared, ready to act. */
"ready" | 
/**  Context discarded as stale or contaminated. */
"purged" | 
/**  Context branched into alternative paths. */
"forked";

/**
 *  A snapshot of the RRO machine at a point in time.
 * 
 *  Returned by `get_rro_state` Tauri command. Emitted as the payload of
 *  `platform:rro-state-changed` Tauri events.
 */
export type RroStateSnapshot = {
	/**  Current state. */
	state: RroState,
	/**  Current rumination depth. */
	depth: RroDepth,
	/**  Opaque origin identifier (per registry `rro.source`). */
	source: string,
	/**  Unix epoch milliseconds of the last transition. */
	last_transition_at_ms: number,
	/**  Diagnostic proximity (0.0..1.0) — closer to 1.0 = closer to friction. */
	proximity: number,
	/**  Recent transitions (newest first, capped at `TRANSITION_HISTORY_CAP`). */
	history: RroStateTransition[],
};

/**  A single transition record. Held in the ring buffer for replay. */
export type RroStateTransition = {
	/**  Previous state (None for the initial transition into `idle`). */
	from: RroState | null,
	/**  New state after this transition. */
	to: RroState,
	/**  Unix epoch milliseconds when the transition occurred. */
	at_ms: number,
	/**  Opaque source/reason — per registry, never an algorithm name. */
	reason: string,
};

/**
 *  Identifies the engine fulfilling a capability slot at a moment in time.
 * 
 *  The loader stamps a fingerprint on every successful load and caches
 *  the previous one per slot. When the next load produces a different
 *  `runtime_id`, the engine fires [`LoaderEvent::CapabilityRebound`] —
 *  when only `crate_version` / `upstream_revision` / `model_revision`
 *  differ, it fires [`LoaderEvent::RuntimeVersionChanged`] instead.
 * 
 *  All four version fields are optional because they're discovered at
 *  load time from heterogeneous sources (cargo metadata, vendored fork
 *  SHA stamps, `HuggingFace` LFS oid). A missing field means "not known
 *  for this runtime"; the loader still produces a stable fingerprint
 *  because `runtime_id` alone is sufficient for rebind detection.
 */
export type RuntimeFingerprint = {
	/**
	 *  Stable runtime handle — `"candle"`, `"llama-server"`, `"ort"`,
	 *  `"sherpa-onnx-asr"`, `"qwen3-tts-candle"`, `"ollama-external"`,
	 *  `"mistralrs"`, `"siglip2-onnx-fixres"`, … Matches the
	 *  `runtimeId` a desktop devtool folder declares in `_devtool`.
	 */
	runtime_id: string,
	/**
	 *  Cargo crate version of the runtime crate
	 *  (`env!("CARGO_PKG_VERSION")` at runtime). `None` for runtimes
	 *  that don't ship as a Rust crate (Ollama, system services).
	 */
	crate_version: string | null,
	/**
	 *  Git commit SHA for vendored forks (`deps/moshi/`, `deps/ort/`,
	 *  kokoros, …). `None` when the runtime is consumed unmodified.
	 */
	upstream_revision: string | null,
	/**
	 *  SHA-256 of the model weights — already computed by the LFS
	 *  download verifier for HuggingFace-sourced models. Lets the UI
	 *  distinguish "same runtime, new model file" from "same model,
	 *  new runtime version".
	 */
	model_revision: string | null,
};

/**
 *  Copy for the post-login runtime picker — the embedder selector
 *  + minion read-only section rendered at `/profile`.
 * 
 *  Distinct from `ProfileCopy` (wizard's "tell me about yourself"
 *  step). Named `RuntimePickerCopy` so the two never collide in
 *  either Rust or TS bindings.
 * 
 *  All templates use `{repo}`, `{size_mb}`, `{error}` placeholders the
 *  frontend substitutes. Layman English only — no jargon like "slot,"
 *  "runtime," "preset" in the customer-facing strings.
 */
export type RuntimePickerCopy = {
	/**  Heading above the embedder picker section. */
	heading: string,
	/**  One-line subtitle below the heading. */
	subtitle: string,
	/**  Label above the repo-id input. */
	repo_field_label: string,
	/**  Placeholder inside the repo-id input. */
	repo_field_placeholder: string,
	/**  `aria-label` on the repo-id input. */
	repo_field_aria: string,
	/**  Visible "Apply" button label. */
	apply_label: string,
	/**  `aria-label` on the Apply button. */
	apply_aria: string,
	/**  Apply button label while the install chain is in flight. */
	apply_busy_label: string,
	/**  Template — current loaded variant. Placeholder `{repo}`. */
	status_currently_using_template: string,
	/**  Template — recommended variant from the system scan. Placeholder `{repo}`. */
	status_recommended_template: string,
	/**  Template — success line after apply. Placeholders `{repo}` + `{size_mb}`. */
	status_applied_template: string,
	/**  Template — failure line. Placeholder `{error}`. */
	status_failed_template: string,
	/**  Heading above the minion read-only section. */
	minion_section_heading: string,
	/**  Template subtitle below the minion heading. Placeholder `{repo}`. */
	minion_section_subtitle_template: string,
};

/**
 *  Result of `check_runtime_updates` — surfaces whether a newer
 *  version of a runtime is available without committing the user
 *  to anything. The UI shows the message verbatim; if `status` is
 *  `UpdateAvailable`, an "Update now" action becomes available
 *  (Phase 5 follow-up wires the actual swap).
 * 
 *  `source_url` is set when the runtime has a known upstream
 *  (`HuggingFace` repo, GitHub releases, crates.io page) — the UI
 *  renders it as an external link so the user can manually
 *  inspect the upstream changelog before triggering an update.
 */
export type RuntimeUpdateInfo = {
	/**  Runtime that was checked. */
	runtime_id: string,
	/**  Outcome of the check. */
	status: RuntimeUpdateStatus,
	/**
	 *  Fingerprint at the time of the check, if the runtime is
	 *  currently loaded. `None` when the runtime isn't in any slot.
	 */
	current_fingerprint: RuntimeFingerprint | null,
	/**  Layman-language summary of the result. */
	message: string,
	/**  Upstream source the user can inspect manually, if any. */
	source_url: string | null,
};

/**  Outcome of a runtime update check. */
export type RuntimeUpdateStatus = 
/**  Runtime is at the latest known version. */
"up_to_date" | 
/**  A newer version exists upstream. */
"update_available" | 
/**
 *  No upstream check is implemented for this runtime yet —
 *  the UI shows a tooltip explaining the status.
 */
"no_check_configured" | 
/**
 *  Upstream check ran but failed (network, parse, rate-limit).
 *  `message` carries the error detail.
 */
"check_failed";

/**  Save intent. A missing identity creates a new connection; an existing one edits it. */
export type SaveConnection = {
	/**  Identity to edit, or None for a new connection. */
	id: string | null,
	/**  User-chosen name. */
	label: string,
	/**  Request/response adapter. */
	provider: ProviderId,
	/**  Explicit API base URL. */
	endpoint: string,
	/**  Backend-only credential intent; never returned or logged. */
	credential: ConnectionCredential,
};

/**  Public configuration. No credential or vault reference crosses this boundary. */
export type SavedConnection = {
	/**  Stable connection identity, independent of provider or label. */
	id: string,
	/**  Changes on every edit, preventing stale conversation routing. */
	revision: number,
	/**  User-chosen name. */
	label: string,
	/**  Request/response adapter to use. */
	provider: ProviderId,
	/**  Explicit API base, including its version/path prefix. */
	endpoint: string,
	/**  A private vault reference is saved; a check still must resolve it. */
	hasCredential: boolean,
	/**  Evidence for this configuration during this process lifetime only. */
	check: ConnectionCheck | null,
	/**  Most recent explicit text test, scoped to the selected model. */
	textTest: ConnectionTextTest | null,
};

/**  Scanning state — shown during hardware detection. */
export type ScanningCopy = {
	/**  Heading displayed while the hardware probe is running (e.g. "Checking your gear…"). */
	title: string,
	/**  Secondary line that reassures the user while detection is in progress. */
	subtitle: string,
	/**  Alt text for the animated Clyffy mascot shown during the scanning state. */
	mascot_alt: string,
};

/**
 *  One parsed JSONL log line, projected to the fields the devtool renders.
 * 
 *  Skips spans/fields/file/line — the JSONL has them but the devtool's
 *  scoped-log panel only needs timestamp + level + target + message. A
 *  future "log details" drawer can re-parse the raw JSON if needed.
 */
export type ScopedLogEntry = {
	/**  ISO-8601 timestamp from the JSONL `timestamp` field. */
	timestamp: string,
	/**  Log level: `TRACE` / `DEBUG` / `INFO` / `WARN` / `ERROR`. */
	level: string,
	/**
	 *  Tracing target — e.g. `devtools.claude`, `mcp_stdio_server`,
	 *  `claude::mcp::tools::query_database`.
	 */
	target: string,
	/**
	 *  Human-readable message from the JSONL `fields.message` field.
	 *  Empty string if the entry was a span event without a message.
	 */
	message: string,
};

/**  One seat: a role, how many sit in it, and the role's parameters filled. */
export type Seat = {
	/**  The seat's name in this room; phases refer to it. */
	seat: string,
	/**  `role-id@major` (`skeptic@1`). */
	role: string,
	/**  How many sit in it (1–6). */
	count: number,
	/**  The role's parameters, filled. */
	parameters?: { [key in string]: string },
	/**
	 *  It gets the notes you chose: yes unless you say otherwise, here or when
	 *  you seat the room.
	 */
	notes?: boolean,
	/**  The persona each place speaks as by default, in order. */
	personas?: string[],
	/**  One line a router reads to choose this seat. */
	summary?: string | null,
};

/**
 *  How the room chooses one answer (select, never blend).
 * 
 *  Four independent switches, field for field the `selection` object of
 *  `dpl.room/1` (as `Capabilities` mirrors its published shape). Grouping
 *  them would need serde's `flatten`, which cannot be combined with
 *  refusing unknown fields.
 */
export type Selection = {
	/**  Who picks. */
	method: SelectionMethod,
	/**  The selector's seat. */
	seat: string,
	/**  See [`Blind`]. */
	blind: Blind,
	/**  See [`SwapOrder`]. */
	swap_order: SwapOrder,
	/**  See [`ExcludeAuthorVendors`]. */
	exclude_author_vendors: ExcludeAuthorVendors,
	/**  See [`AllowNone`]. */
	allow_none: AllowNone,
};

/**  How one answer is chosen. */
export type SelectionMethod = 
/**  One selector picks. */
"judge" | 
/**  Several selectors pick together. */
"panel" | 
/**  The seats vote. */
"vote" | 
/**  You pick. */
"human";

/**
 *  UI grouping bucket for a boot step.
 * 
 *  The TypeScript-literal form (`as_ts_literal`) must stay aligned with
 *  `SubsystemGroupKind` in `interfaces/desktop/src/lib/layouts/app/StatusBar.types.ts`.
 *  `cargo xtask generate-ts-manifest` emits the TS source from this enum.
 */
export type ServiceGroup = 
/**  Data stores: Turso, `DuckDB`, `Moka`. */
"stores" | 
/**  Graph services: `SurrealDB` namespaces + HTTP sidecar. */
"graph" | 
/**  AI capability surface: Model Loader, Vector store. */
"ai" | 
/**  Platform plumbing: preflight, Grammar service, etc. */
"system";

/**  Explicit diagnosis for UI and control-plane consumers. */
export type ServiceIssue = {
	/**  Stable reason for programmatic consumers. */
	code: ServiceIssueCode,
	/**  Actual failure or explanation; never used as an identity. */
	message: string,
};

/**  Machine-readable reason, separate from the human-readable detail. */
export type ServiceIssueCode = 
/**  No operation-level health check is wired for this service. */
"unverified" | 
/**  The service adapter's health operation failed. */
"probe-failed" | 
/**  The health operation did not complete within its deadline. */
"probe-timed-out" | 
/**  Service lifecycle is not ready despite a successful health operation. */
"lifecycle-not-ready" | 
/**  Supervised process startup, transport or cleanup failed. */
"runtime-failed";

/**  A point-in-time observation. It does not grant permission to execute work. */
export type ServiceObservation = {
	/**  Existing adapter lifecycle, when an adapter is present. */
	lifecycle: ServiceState | null,
	/**  Separately verified availability. */
	readiness: ServiceReadiness,
	/**  Source of the observation. */
	evidence: ObservationEvidence,
	/**  When this snapshot was observed, Unix milliseconds (not a lease). */
	observed_at_ms: number,
	/**  Time taken by this health probe; absent when no probe ran. */
	latency_us: number | null,
	/**  Structured failure or explanation. */
	issue: ServiceIssue | null,
};

/**  Availability of the service contract, not of every downstream capability. */
export type ServiceReadiness = 
/**  A real service check succeeded and lifecycle permits work. */
"ready" | 
/**  The service is unavailable, failed or still starting/stopping. */
"not-ready" | 
/**  No operation-level readiness evidence is available. */
"unknown";

/**
 *  Identifies a service's role in the platform.
 * 
 *  `Deserialize` is required by `InternalEvent::SidecarPhaseTransition`
 *  — the broadcast bus carries `Serialize + Deserialize` payloads so
 *  subscribers can round-trip events through OTLP/JSONL exports.
 */
export type ServiceRole = 
/**  Relational service (Turso). */
"Relational" | 
/**  Analytics service (`DuckDB`). */
"Analytics" | 
/**  Graph service (`SurrealDB`). */
"Graph" | 
/**  In-memory cache (`Moka`). */
"Cache" | 
/**  Vector service (`RRO`). */
"Vector" | 
/**  Grammar service (kernel-owned constrained decoding). */
"Grammar" | 
/**  `DevForge` service (managed REH web server). */
"DevForge" | 
/**  Model Loader service (AI model management, inference). */
"ModelLoader" | 
/**  Ollama service (managed `ollama serve` child process). */
"Ollama" | 
/**  Surreal service (managed `surreal start` child process). */
"Surreal" | 
/**  Bundled AI ticket/history runtime, started on demand. */
"AgentHub";

/**
 *  Whether a service is actually alive right now.
 * 
 *  Complements the static `compiled_in` / `config_enabled` fields —
 *  this is the dynamic signal that can change after boot (`DevForge`
 *  lazy-start, `Ollama` sidecar start/stop, grammar toggle).
 */
export type ServiceRuntimeState = 
/**  Cargo feature not compiled in. Not available in this build. */
"not-compiled" | 
/**  Compiled in, but `enabled = false` in config. */
"config-disabled" | 
/**
 *  Compiled + config-enabled, but the service Arc is currently absent
 *  (lazy service not yet started, or boot skipped it).
 */
"stopped" | 
/**  Service Arc is present — it booted and hasn't been torn down. */
"running" | 
/**  Process startup or handshake has not completed. */
"starting" | 
/**  Shutdown is in progress; new operations are unavailable. */
"stopping" | 
/**  The runtime or its startup failed. */
"failed" | 
/**
 *  Runtime state cannot be reported (e.g. no accessor on Platform).
 *  Caller should rely on `compiled_in` / `config_enabled` instead.
 */
"unknown";

/**
 *  Lifecycle state of a platform service.
 * 
 *  Enterprise boot state machine. Services transition through these states
 *  during boot and runtime. The platform never lies about service state.
 */
export type ServiceState = 
/**  Service constructed but boot not yet attempted. */
"Created" | 
/**  Boot in progress — initializing engine, opening files, connecting. */
"Booting" | 
/**  Boot completed and health check passed. Serving requests. */
"Ready" | 
/**  Was ready, but health check failed. May recover on next ping. */
"Degraded" | 
/**  Boot failed or unrecoverable error. Not serving. */
"Failed";

/**
 *  Public, TS-exported snapshot of one entry in [`SERVICE_MANIFEST`]
 *  at a single point in time.
 */
export type ServiceStatusSnapshot = {
	/**  Stable scope/role identity; display names and file paths are not identifiers. */
	service_id: string,
	/**  Role identifier — maps to [`ServiceRole`]. */
	role: ServiceRole,
	/**  Scope bucket — maps to [`DataScope`]. */
	scope: DataScope,
	/**  Boot stage number from the manifest. */
	stage: number,
	/**  Public name ("Vector Store", "Grammar Engine", …). */
	public_name: string,
	/**  UI grouping literal — matches `ServiceGroup::as_ts_literal`. */
	group: ServiceGroup,
	/**  Cargo feature that gates this service. `None` = always compiled. */
	feature_gate: string | null,
	/**  `InitEvent` `step_id` (absent for lazy services). */
	step_id: string | null,
	/**  Was the feature compiled into this build? */
	compiled_in: boolean,
	/**  `enabled = true` in the TOML config? */
	config_enabled: boolean,
	/**  `critical = true` in the TOML config? */
	config_critical: boolean,
	/**  Dynamic runtime liveness — see [`ServiceRuntimeState`]. */
	runtime_state: ServiceRuntimeState,
	/**  Readiness evidence independent of configuration and object presence. */
	observation: ServiceObservation,
};

