/**  Produces ideas or answers. */
"generate" | 
/**  Checks claims against sources. */
"ground" | 
/**  Finds weaknesses in an answer. */
"critique" | 
/**  Attacks an answer to make it fail. */
"adversarial" | 
/**  Turns ideas into steps. */
"plan" | 
/**  Picks one answer, never merging several. */
"select";

/**  Every state signal's latest value at one revision. */
export type StateSnapshot = {
	/**
	 *  Identifies this process run (UUID v7). A different epoch means the
	 *  consumer's copy is from an earlier run and must be discarded.
	 */
	epoch: string,
	/**  Highest revision recorded when the snapshot was taken. */
	revision: number,
	/**  The latest signal of every state kind, oldest revision first. */
	signals: Signal[],
};

/**  One step of the recommendation. */
export type Step = {
	/**  What it does. */
	kind: StepKind,
	/**  The product it acts on. */
	product: string,
};

/**  A setup step, run only when you click it. */
export type StepKind = 
/**  Install WSL (Windows; administrator, then a restart). */
"install_wsl" | 
/**  Update WSL (Windows). */
"update_wsl" | 
/**  Install the product. */
"install" | 
/**  Start the engine (or create and start its machine). */
"start" | 
/**  Run a test container. */
"test";

/**  What running a step did. */
export type StepRun = {
	/**  The step. */
	step: Step,
	/**  It finished successfully. */
	ok: boolean,
	/**  Nothing was run: the output is what to do yourself. */
	guided: boolean,
	/**  Windows must restart before the next step. */
	restartNeeded: boolean,
	/**  The commands run, one per line, as typed. */
	commands: string[],
	/**  The tools' own output (the end of it, when long). */
	output: string,
	/**  Unix seconds when it finished. */
	finishedAt: number,
};

/**  When the room stops. */
export type StopRule = {
	/**  Rounds at most (1–10). */
	max_rounds: number,
	/**  Tokens the whole room may spend. */
	budget_tokens?: number | null,
	/**  Stop when no answer changed in a round. */
	stability?: boolean,
	/**  Stop when the rubric passes. */
	pass_threshold?: boolean,
};

/**  Why the rounds stopped. */
export type Stopped = 
/**  The room's last round ran. */
"rounds" | 
/**  No author changed its answer in a round. */
"stable" | 
/**  Every critique reported no defects. */
"passed";

/**
 *  Result of a full STS (speech-to-speech) pipeline run.
 * 
 *  The pipeline: uploaded audio → STT (transcript) → brain (reply) → TTS (audio).
 *  Returns both the transcript and the reply text so the UI can display
 *  the conversation turn. The TTS audio is played directly through the
 *  default output device — it is not returned over IPC.
 */
export type StsPipelineResult = {
	/**  Transcript produced by the STT stage. */
	transcript: string,
	/**  Reply text produced by the brain stage. */
	reply: string,
	/**  TTS voice used to synthesize the reply. */
	voice: string,
};

/**  Health of an individual subsystem (database, cache, etc.). */
export type SubsystemHealth = {
	/**  Stable identity from the service manifest. */
	service_id: string,
	/**  Group declared by the manifest, never inferred from translated labels. */
	group: ServiceGroup,
	/**  Presentation label from the same manifest. */
	name: string,
	/**  Observed adapter lifecycle; absent when unavailable or unverified. */
	state: ServiceState | null,
	/**  Health derived from the inventory's readiness evidence. */
	status: HealthStatus,
	/**
	 *  Ping latency in microseconds. Microseconds prevent sub-millisecond
	 *  operations from rounding to 0 and lying about their cost.
	 */
	latency_us: number | null,
	/**  Human-readable status message. */
	message: string | null,
};

/**  One suggestion returned by [`SuggestionService::query`]. */
export type Suggestion = {
	/**  Original prompt id (`UUIDv7` — recency-sortable on lex order). */
	id: string,
	/**  Original prompt text the user committed previously. */
	text: string,
	/**
	 *  Closeness in `[0.0, 1.0]`, higher is closer: cosine similarity when
	 *  recalled by meaning, from the word-match score when recalled by
	 *  words.
	 */
	similarity: number,
	/**
	 *  Unix-seconds capture time. Used by the recency factor in the
	 *  final rank.
	 */
	capturedAt: number,
	/**  Whether the original prompt was accepted (boosts rank). */
	accepted: boolean,
	/**
	 *  Final fused score after recency × similarity × accepted-boost
	 *  reweighting. Sorted in descending order in the returned vec.
	 */
	score: number,
};

/**
 *  Full Supabase client envelope returned to the frontend so it can
 *  instantiate `supabase-js` with `createClient(url, anon_key)`.
 * 
 *  `anon_key` is `None` when the operator hasn't run setup yet; the
 *  auth shell renders the "Supabase isn't configured" empty state in
 *  that case rather than crashing on a null key.
 */
export type SupabaseCredentials = {
	/**  HTTPS API URL — feeds `createClient(url, ...)`. */
	url: string,
	/**
	 *  The public anon key: the keychain's override, else the configured
	 *  key. `None` when neither is set, or no URL is configured.
	 */
	anonKey: string | null,
};

/**
 *  Frontend-safe status used by the Cloud settings devtool — exposes
 *  whether the key is stored plus a masked preview, never the raw value.
 */
export type SupabaseCredentialsStatus = {
	/**  HTTPS API URL — same shape as `SupabaseCredentials::url`. */
	url: string,
	/**  `true` when the configuration holds an anon key. */
	anonKeyConfigured: boolean,
	/**  `true` when an anon key is in the OS keychain (it overrides the configured one). */
	anonKeyStored: boolean,
	/**
	 *  First-8-chars-then-mask preview, e.g. `eyJhbGci...****`. `None`
	 *  when no key is stored.
	 */
	anonKeyPreview: string | null,
};

/**
 *  Whether the backend for this format is stable, experimental, or
 *  not yet shipped. Used by the resolver to decide whether to surface
 *  a compatibility warning alongside a successful plan.
 */
export type SupportStatus = 
/**  Shipped and expected to work in routine use. */
"stable" | 
/**  Shipped behind cautionary messaging due to maturity risk. */
"experimental" | 
/**  Declared in the registry but not yet implemented. */
"planned" | 
/**  Explicitly unsupported for this backend/format pairing. */
"unsupported";

/**  Relative priority for recommendation order. */
export type SupportTier = 
/**  First-class path shown as the default recommendation. */
"primary" | 
/**  Supported fallback path when the primary tier is not available. */
"secondary" | 
/**  Deprecated but still loadable for existing model inventories. */
"legacy" | 
/**  Reserved entry that should render as coming soon, not loadable. */
"planned";

/**  Serde-friendly health probe result. */
export type SurrealHealth = {
	/**  `"up"` / `"down"` / `"stopped"`. */
	state: string,
	/**  Human-readable label (short). */
	label: string,
};

/**
 *  Runtime status of the Surreal server — what the devtool renders (plan
 *  0007 S7): the live process, the port it got, the build it runs, its
 *  restarts, and where the bytes live.
 */
export type SurrealStatus = {
	/**  The server process is alive. */
	running: boolean,
	/**
	 *  `DevPulse` started and owns the server (always: it never attaches to
	 *  one it did not start).
	 */
	managed: boolean,
	/**  Storage engine, e.g. `"surrealkv (server)"`. */
	backend: string,
	/**  The store folder. */
	dataPath: string,
	/**
	 *  `starting` / `ready` / `restarting` / `stopped` / `failed`;
	 *  `not started` when boot skipped or failed it.
	 */
	state: string,
	/**  Why it failed, or which restart this is. */
	stateDetail: string | null,
	/**  The server's process id, while it runs. */
	pid: number | null,
	/**  The server build it runs. */
	binary: string,
	/**  The version the server reported (`surrealdb-3.0.5`). */
	version: string | null,
	/**  Its address, e.g. `http://127.0.0.1:8822`. */
	endpoint: string | null,
	/**  The port configuration asked for. */
	configuredPort: number | null,
	/**  The port it got (higher when the configured one was taken). */
	actualPort: number | null,
	/**  Restarts after a crash since `DevPulse` started it. */
	restarts: number,
	/**  When it last started answering (RFC 3339). */
	readySince: string | null,
};

/**
 *  Persisted user overrides for the Surreal embedded store.
 * 
 *  Reserved for future tuning knobs (cache size, compaction policy,
 *  snapshot retention). Empty today — the embedded path has no
 *  port / binary / auth fields a user would override.
 */
export type SurrealUserConfig = Record<string, never>;

/**  Judge in both orders; a disagreement is a tie or a rerun. */
export type SwapOrder = boolean;

/**
 *  Result of a single [`BurnEncoderAdapter::swap_blocking`] cycle.
 * 
 *  Mirrors the `SwapReport` interface the desktop devtool consumes via
 *  the `cortex_swap_encoder` Tauri command (see
 *  `interfaces/desktop/src/lib/devtools/clyffy/reasoning/rrd/data-access/swap.svc.ts`).
 *  Fields are flat + plain types so the value crosses straight to the
 *  frontend under specta when the consuming crate enables the feature.
 */
export type SwapStats = {
	/**
	 *  Output dimension of the new encoder (e.g. 1024 for Harrier 0.6B).
	 *  Read off the live forward pass — authoritative against the
	 *  loaded weights, not a config.json shadow.
	 */
	dim: number,
	/**
	 *  Total wall-clock time the maintenance window was held, in ms.
	 *  Includes pause/drain + load + validate + swap + resume.
	 */
	elapsed_ms: number,
	/**
	 *  Phase names the daemon traversed during the swap, in order. The
	 *  canonical sequence on a healthy swap is `pause_requested`,
	 *  `drain_complete`, `load_complete`, `validate_pass`, `swap_commit`,
	 *  `resume_complete`. Use `phases_observed.last()` to confirm the
	 *  daemon settled at `resume_complete`.
	 */
	phases_observed: string[],
};

/**
 *  Outcome of a [`sync_community_feed`] invocation.
 * 
 *  `Synced` is the happy path; `Skipped` means we declined to call out
 *  (cache is fresh, or community is disabled); `Failed` carries a
 *  stringified reason for the UI to surface inline.
 */
export type SyncResult = 
/**  Sync ran and `upserted` rows landed in the local cache. */
{ kind: "synced"; 
/**  Number of rows upserted into `community_feed`. */
upserted: number; 
/**  Epoch seconds when the sync completed. */
completed_at: number } | 
/**  Sync skipped intentionally — cache fresh, disabled, or no creds. */
{ kind: "skipped"; 
/**  Human-readable reason. */
reason: string } | 
/**  Sync attempted and failed — message describes the failure. */
{ kind: "failed"; 
/**  Stringified error from the failing layer. */
error: string };

